drop policy if exists "school_documents_admin_insert" on storage.objects;
create policy "school_documents_admin_insert" on storage.objects for insert to authenticated with check (bucket_id='school-documents' and exists (select 1 from public.user_profiles where id=(select auth.uid()) and role::text='admin' and is_active=true));
drop policy if exists "school_documents_admin_update" on storage.objects;
create policy "school_documents_admin_update" on storage.objects for update to authenticated using (bucket_id='school-documents' and exists (select 1 from public.user_profiles where id=(select auth.uid()) and role::text='admin' and is_active=true)) with check (bucket_id='school-documents' and exists (select 1 from public.user_profiles where id=(select auth.uid()) and role::text='admin' and is_active=true));
drop policy if exists "school_documents_admin_delete" on storage.objects;
create policy "school_documents_admin_delete" on storage.objects for delete to authenticated using (bucket_id='school-documents' and exists (select 1 from public.user_profiles where id=(select auth.uid()) and role::text='admin' and is_active=true));
drop policy if exists "school_documents_authorized_read" on storage.objects;
create policy "school_documents_authorized_read" on storage.objects for select to authenticated using (bucket_id='school-documents' and exists (select 1 from public.user_profiles profile where profile.id=(select auth.uid()) and profile.is_active=true and (profile.role::text='admin' or exists (select 1 from public.school_documents document where document.file_url=storage.objects.name and document.is_published=true and (document.audience='all' or document.audience=profile.role::text)))));